        title: article.title,
        brief: "",
        content,
        channelId: 24,
        categoryId: -1,
        id: 0,
        userColumnId: 0,
        columnNewsIds: [],
        businessCode: 0,
        declareOriginal: false,
        cover: "",
        topicIds: [],
        isAd: 0,
